INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (30,20,'',1,'从 ARPANET 到智能互联：互联网发展简史与未来图景','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/99821e313f7b7c44c8cff47265684c8b.png','',1,0,0,0,0,1,0,'',1,'','','超级管理员',343,0,'从 ARPANET 到智能互联：互联网发展简史与未来图景','','互联网是近半个世纪以来改变人类生产与生活方式最深远的技术力量之一。它从一项面向科研与国防的小型实验网络起步，逐步成长为覆盖全球、连接数十亿人的数字基础设施。理解互联网的发展脉络，有助于我们看清技术演进的规律，以及数字社会未来的方向。 一、萌芽阶段：从军用科研网络到分组交换 20 世纪 60 年代，计算机之间还无法有效通信。1969 年，美国高级研究计划局主持的 ARPANET 完成了四个节点之间的',1,0,'cn',1,0,0,0,0,0,'',1794331123,1794331123,0,1794331123);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (31,20,'',1,'互联网重塑日常：社交、办公、消费与学习的数字变迁','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/56e1b04c3d0252b83b2d468b01100ec8.png','',1,0,0,0,0,1,0,'',1,'','','超级管理员',272,0,'互联网重塑日常：社交、办公、消费与学习的数字变迁','','如果说早期互联网改变的是 \"信息能否被检索\"，那么今天的互联网改变的则是 \"生活如何被组织\"。从联络朋友、处理工作，到购物消费和获取知识，网络已经嵌入日常生活的方方面面。本文从社交、办公、消费与学习四个维度，观察互联网带来的日常变迁。 一、社交：从线下碰面到全天候在线连接 即时通讯、社交网络和分享平台让人与人的联络摆脱了时间与空间的限制。亲友可以随时发送消息、语音或视频，远距离的关系得以高频维持；',1,0,'cn',1,0,0,0,0,0,'',1794331251,1794331251,0,1794331251);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (32,20,'',1,'数字时代的互联网安全与治理：隐私保护、虚假信息与可信网络','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/abc87d68123e53adb240beac3512e296.png','',1,0,1,0,0,0,0,'',1,'','','超级管理员',299,0,'数字时代的互联网安全与治理：隐私保护、虚假信息与可信网络','','互联网在带来连接与便利的同时，也把网络安全、个人隐私和信息秩序等问题带到每个人面前。数据在网络中流转，服务依赖平台运行，如何在开放共享与安全可信之间取得平衡，是数字社会必须回答的课题。 一、网络安全：常见威胁与防护基线 网络威胁形式多样，常见的包括钓鱼链接与诈骗邮件、恶意软件、账号被盗、数据泄露以及针对设备和系统的攻击。基础防护并不复杂：使用复杂度足够且不重复的密码、开启双重验证、谨慎点击陌生链接',1,0,'cn',1,0,0,0,0,0,'',1794331382,1794331382,0,1794331382);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (33,21,'',1,'互联网经济与产业变革：电商、平台经济与数字新业态','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/dcf57866f1d5aeeca012395a7456d67f.png','',1,1,1,0,0,0,0,'',1,'','','超级管理员',493,0,'互联网经济与产业变革：电商、平台经济与数字新业态','','互联网不仅改变了信息的传递方式，也重构了交易流程、组织形态和产业分工。在线上与线下不断融合的过程中，新的商业模式、服务形态和就业机会持续涌现，数字经济成为推动产业升级的重要力量。 一、电子商务：从货架上网到全渠道零售 早期电商主要把商品搬到线上展示和销售；随着支付、物流和评价体系成熟，线上选购、线下体验、即时配送等全渠道方式逐渐普及。商品信息透明、比价便利，消费选择被极大拓宽，零售行业的流程与效率',1,0,'cn',1,0,0,0,0,0,'',1794331617,1794331617,0,1794331617);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (34,21,'',1,'人工智能与互联网：从信息检索到智能服务的演进','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/4f225b65fb6285d5c4912c65fde6851b.png','',1,1,1,0,0,0,0,'',1,'','','超级管理员',265,0,'人工智能与互联网：从信息检索到智能服务的演进','','互联网积累的海量数据与持续进步的算法相结合，推动人工智能进入日常网络服务。人机交互正从“人寻找信息”，逐步转向信息与服务主动理解需求、提供辅助，互联网因此具备了越来越强的“智能”属性。 一、搜索与推荐：信息分发的智能化 搜索引擎和推荐系统根据用户行为与内容特征进行匹配，让信息分发更加个性化。短视频、资讯、商品和服务的推荐，本质上是在海量内容与个体需求之间做高效连接；推荐效率提升的同时，也需要注意信',1,0,'cn',1,0,0,0,0,0,'',1794331654,1794331654,0,1794331654);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (35,21,'',1,'物联网与万物互联：智能设备、智慧城市与产业联网','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/51700122e5e386ba992abbe0b50f30f7.png','',1,1,1,0,0,0,0,'',1,'','','超级管理员',273,0,'物联网与万物互联：智能设备、智慧城市与产业联网','','互联网最初主要连接人与信息，随着传感器和联网设备普及，网络开始连接机器、物品和物理世界。设备之间实时交换数据，使家居、城市和生产系统具备感知、分析与自动响应能力，这就是物联网带来的变革。 一、物联网的基本构成：感知、网络与数据 物联网由感知层、网络层和应用层组成：传感器与设备采集温度、位置、状态等数据，通过网络传输到平台，再经过分析支撑控制与决策。数据是物联网运行的核心，设备联网只是起点，数据如何',1,0,'cn',1,0,0,0,0,0,'',1794331677,1794331677,0,1794331677);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (36,19,'',1,'互联网文化与媒介变迁：短视频、流媒体与数字内容创作','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/89c1a73d44e4226346f9f58ec07b92d4.png','',1,0,0,0,0,0,0,'',1,'','','超级管理员',365,0,'互联网文化与媒介变迁：短视频、流媒体与数字内容创作','','互联网不仅改变了信息怎么传，也改变了内容怎么做、怎么看。媒介形态从图文走向视频与互动，创作门槛持续降低，普通人成为内容生产者，新的流行文化和话语方式也在网络社群中不断生长。 一、图文到视频：媒介形态的迁移 随着网络带宽和终端性能提升，内容消费从文字、图片逐步扩展到短视频、直播和长视频。视频以更直观的方式传递信息与情绪，成为注意力竞争的重要媒介；不同形态各有优势，图文的深度与视频的直观互为补充。 二',1,0,'cn',1,0,0,0,0,0,'',1794331704,1794331704,0,1794331704);
INSERT INTO `miu_document` (`id`,`nav_id`,`sub_nav_ids`,`channel_id`,`title`,`short_title`,`title_ext_1`,`title_ext_2`,`title_ext_3`,`litpic`,`title_color`,`is_original`,`is_head`,`is_special`,`is_b`,`is_top`,`is_recommend`,`is_jump`,`jumplinks`,`is_litpic`,`from`,`from_url`,`author`,`click`,`arcrank`,`seo_title`,`seo_keywords`,`seo_description`,`status`,`sort`,`lang`,`admin_id`,`arc_level_id`,`restric_type`,`is_del`,`appraise`,`collection`,`tag_ids`,`add_time`,`update_time`,`delete_time`,`release_time`) VALUES (37,19,'',1,'互联网的未来趋势：高速网络、沉浸式体验与可持续数字社会','','','','','https://miucms.oss-cn-beijing.aliyuncs.com/202611/2dfedc6377a1f0045f10728a68a22019.png','',1,0,0,0,0,0,0,'',1,'','','超级管理员',483,0,'互联网的未来趋势：高速网络、沉浸式体验与可持续数字社会','','互联网仍在快速演进。展望未来，网络速度、交互形态、算力分布和资源效率都将持续变化，技术与社会需求相互推动，把互联网带向更深融合、更加沉浸，也更强调可持续的方向。 一、更高速的网络：通信技术的持续升级 网络代际演进不断提升带宽、降低延迟，为高清视频、实时互动和大规模设备连接提供基础。更快的网络使远程协作、实时控制和高密度在线服务成为可能，也对覆盖范围、资费水平和接入公平性提出了更高要求。 二、沉浸式',1,0,'cn',1,0,0,0,0,0,'',1794331727,1794331727,0,1794331727);
