INSERT INTO `miu_clue` (`id`,`doc_id`,`content`,`md_content`,`add_time`,`update_time`,`delete_time`) VALUES (2,27,'<p>感谢您选择MiuCMS。如果您在使用过程中遇到任何问题，或需要产品咨询、售后支持与意见反馈，欢迎通过以下方式与我们联系：</p>\r\n<ul>\r\n<li>客服热线：XXX-XXXX-XXXX（服务时间：周一至周日 XXX:XXX–XXX:XXX）</li>\r\n<li>官方邮箱：XXX@email.com.</li>\r\n<li>在线客服：打开本机 \"服务与反馈\" 应用，即可提交问题并查询处理进度</li>\r\n<li>服务网点：可在官方网站 \"服务支持 — 网点查询\" 中查看就近服务中心（网址：XXX）</li>\r\n</ul>\r\n<p>我们会在收到您的信息后尽快回复。您的建议将帮助我们持续改进产品与服务。</p>\r\n<div class=\"contact\">\r\n<div class=\"media media-x\">\r\n<div class=\"media-body\"> </div>\r\n</div>\r\n</div>','',0,1794333833,0);
