INSERT INTO `miu_single` VALUES ('1', '16', '<h2><span class=\"smd-text-chunk\">关于 MiuCms</span></h2>\r\n<p><span class=\"smd-text-chunk\">M</span><span class=\"smd-text-chunk\">iuCms 是一套基于 ThinkPHP 8、Layui 和 MySQL 的内容管理系统。它面向企业官网、资讯门户、分类信息、房产、课程教育等常见站点，也给开发者留出足够的空间做二次开发。</span></p>\r\n<h3><span class=\"smd-text-chunk\">为什么做这套系统</span></h3>\r\n<p><span class=\"smd-text-chunk\">很</span><span class=\"smd-text-chunk\">多项目并不需要一个庞大的建站平台：客户要的是能快速上线、后台好上手、后期改得动。MiuCms 从这一点出发，把内容模型、栏目、模板和插件拆成可以组合的部分，让一个站点在几天内成型，而不是先花几周去熟悉框架。</span></p>\r\n<h3><span class=\"smd-text-chunk\">它能做什么</span></h3>\r\n<p><span class=\"smd-text-chunk\">后</span><span class=\"smd-text-chunk\">台可以自定义内容模型和字段，按业务需要维护文档；前台模板通过标签读取栏目、文档、标签、广告等数据，改版时不必动后端逻辑。SEO 支持动态、伪静态和生成静态三种 URL 模式，并提供 XML、TXT、HTML 格式的站点地图。会员、附件存储（本地、阿里云 OSS、腾讯云 COS）、多语言和 AI 辅助写作，都以内置模块或插件的方式提供，按需启用。</span></p>\r\n<h3><span class=\"smd-text-chunk\">开源与授权</span></h3>\r\n<p><span class=\"smd-text-chunk\">M</span><span class=\"smd-text-chunk\">iuCms 基于 Apache-2.0 协议开源，永久免费，可用于商业项目和二次开发。基于它搭建并运营的网站，请在页脚保留「Power by MiuCms」。第三方依赖和插件遵循各自的授权协议。</span></p>', '', '0', '1794337099', '0');
INSERT INTO `miu_single` VALUES ('2', '17', '<h2><span class=\"smd-text-chunk\">公司简介</span></h2>\r\n<p><span class=\"smd-text-chunk\">M</span><span class=\"smd-text-chunk\">iuCms 是一套基于 ThinkPHP 8、Layui 和 MySQL 的内容管理系统，面向企业官网、资讯门户、分类信息、房产、课程教育等常见站点，也为开发者留出二次开发的空间。</span></p>\r\n<h3><span class=\"smd-text-chunk\">我们做什么</span></h3>\r\n<p><span class=\"smd-text-chunk\">很</span><span class=\"smd-text-chunk\">多项目并不需要一个庞大的建站平台，客户要的是能快速上线、后台好上手、后期改得动。MiuCms 从这一点出发，把内容模型、栏目、模板和插件拆成可以组合的部分，让一个站点按项目需要逐步搭起来，而不是先花几周去熟悉框架。</span></p>\r\n<h3><span class=\"smd-text-chunk\">产品能力</span></h3>\r\n<p><span class=\"smd-text-chunk\">后</span><span class=\"smd-text-chunk\">台支持自定义内容模型和字段，按业务需要维护文档；前台模板通过标签读取栏目、文档、标签、广告等数据，改版时不必动后端逻辑。SEO 支持动态、伪静态和生成静态三种 URL 模式，并提供 XML、TXT、HTML 格式的站点地图。会员、附件存储（本地、阿里云 OSS、腾讯云 COS）、多语言和 AI 辅助写作，以内置模块或插件的方式提供，按需启用。</span></p>\r\n', '', '0', '1794328076', '0');